SELECT r.id, r.conversation_id, r.created_at, r.queue_seq, r.origin, r.goal_id, r.status_reason, r.status, r.started_by_message_id, r.retry_of, r.agent_id_used, r.agent_config_used_id, r.model_override_provider, r.model_override, r.model_params_override, r.run_id, r.error_message FROM (SELECT data_rows.id, data_rows.should_delete, data_rows.conversation_id, data_rows.created_at, data_rows.queue_seq, data_rows.origin, data_rows.goal_id, data_rows.status_reason, data_rows.status, data_rows.started_by_message_id, data_rows.retry_of, data_rows.agent_id_used, data_rows.agent_config_used_id, data_rows.model_override_provider, data_rows.model_override, data_rows.model_params_override, data_rows.run_id, data_rows.error_message FROM  (SELECT 0 AS should_delete, `id`, `conversation_id`, `created_at`, `queue_seq`, `origin`, `goal_id`, `status_reason`, `status`, `started_by_message_id`, `retry_of`, `agent_id_used`, `agent_config_used_id`, `model_override_provider`, `model_override`, `model_params_override`, `run_id`, `error_message` FROM turn)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)